import { readFileSync } from "node:fs"
import { join } from "node:path"

let cachedB64: string | null = null

const EMBEDDED_ALPHA_PHOTO_B64 =
  ""

/**
 * Returns Alpha's contact photo as a base64-encoded PNG string.
 * Attempts to load from disk assets first, falling back to embedded photo data.
 */
export function getAlphaContactPhotoB64(): string {
  if (cachedB64 !== null) return cachedB64
  const candidates = [
    join(import.meta.dir, "assets", "alpha-contact.png"),
    join(import.meta.dir, "..", "shared", "assets", "alpha-contact.png"),
    join(import.meta.dir, "..", "..", "public", "alpha-contact.png"),
    join(import.meta.dir, "..", "..", "dist", "alpha-contact.png"),
    join(process.cwd(), "spectrum", "shared", "assets", "alpha-contact.png"),
    join(process.cwd(), "public", "alpha-contact.png"),
    join(process.cwd(), "dist", "alpha-contact.png"),
    "/app/spectrum/shared/assets/alpha-contact.png",
    "/app/dist/alpha-contact.png",
    "/app/public/alpha-contact.png",
  ]
  for (const file of candidates) {
    try {
      const buf = readFileSync(file)
      if (buf && buf.byteLength > 0) {
        cachedB64 = buf.toString("base64")
        return cachedB64
      }
    } catch {
      // try next candidate
    }
  }
  cachedB64 = EMBEDDED_ALPHA_PHOTO_B64
  return cachedB64
}

/**
 * Builds a vCard 3.0 string with Alpha's name, assigned line, organization,
 * and the embedded avatar logo photo folded per RFC 2425/RFC 6350.
 */
export function buildAlphaVcard(tel: string = "+14155951440"): string {
  const lines = [
    "BEGIN:VCARD",
    "VERSION:3.0",
    "N:;Alpha;;;",
    "FN:Alpha",
    "ORG:HireAlpha",
    `TEL;TYPE=CELL:${tel}`,
  ]
  const b64 = getAlphaContactPhotoB64()
  if (b64) {
    // Fold counts the whole line: the first chunk fits after the 26-char
    // property prefix and the rest continue at 74 with a leading space.
    const head = "PHOTO;ENCODING=b;TYPE=PNG:"
    const rest = b64.match(/.{1,74}/g) || []
    lines.push(head + rest[0].slice(0, 75 - head.length))
    for (let i = 0; i < rest.length; i++) {
      const part = i === 0 ? rest[0].slice(75 - head.length) : rest[i]
      if (part) lines.push(" " + part)
    }
  }
  lines.push("END:VCARD")
  return lines.join("\r\n")
}
